"""Controlled transport/record checks; not a semantic grader."""
import hashlib
import json
import sys
import unittest
from pathlib import Path

TRIAL = Path(__file__).resolve().parent
ROOT = TRIAL.parents[1]
sys.path.insert(0, str(ROOT))
from tests.test_caddie_context_recovery import preservation_errors, local_target, LINK, SOURCES


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def files_under(directory):
    return {p.relative_to(directory).as_posix(): p.read_text(encoding="utf-8")
            for p in directory.rglob("*") if p.is_file()}


def reachable(files, start="README.md"):
    """Accept a real directory link without inventing links to its children."""
    import re
    seen, pending = set(), [start]
    while pending:
        current = pending.pop()
        if current in seen:
            continue
        if current not in files:
            if any(name.startswith(current.rstrip("/") + "/") for name in files):
                seen.add(current)
                continue
            raise ValueError("missing reference: " + current)
        seen.add(current)
        pending.extend(local_target(current, ref) for ref in LINK.findall(files[current]))
        pending.extend(ref for ref in re.findall(r"`([^`\n]+\.md)`", files[current])
                       if "/" in ref and ref in files)
    return seen


class ConnectedEvidenceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.audit = json.loads((TRIAL / "audit.json").read_text(encoding="utf-8"))
        cls.record = json.loads((TRIAL / "connected-result.json").read_text(encoding="utf-8"))

    def test_no_case_changes_before_edit_authorization(self):
        initial = self.audit["case_before"]
        self.assertEqual(initial, self.audit["case_after_enquiry"])
        self.assertEqual(initial, self.audit["case_after_receipt"])

    def test_delivery_receipt_corresponds_to_saved_request(self):
        receipt = json.loads((TRIAL / "worker/inbox/receipt.json").read_text(encoding="utf-8"))
        self.assertTrue(receipt["simulation_only"])
        self.assertEqual(receipt["request_sha256"], digest(TRIAL / "worker/outbox/request.md"))
        self.assertEqual(receipt["state"], "delivered_to_test_recipient")
        self.assertFalse(receipt["real_transport_verified"])

    def test_record_preserves_history_and_received_sources(self):
        initial = self.record["initial"]
        received = self.record["received"]
        actual = files_under(TRIAL / "worker/case")
        self.assertEqual(preservation_errors(initial, received, actual), [])

    def test_record_and_reader_reach_preserved_originals(self):
        for location in ("worker/case", "successor/case"):
            self.assertTrue(set(SOURCES.values()) <= reachable(files_under(TRIAL / location)))

    def test_existing_directory_is_valid_but_not_automatic_child_reachability(self):
        seen = reachable({"README.md": "[sources](docs/)", "docs/a.md": "a"})
        self.assertIn("docs", seen)
        self.assertNotIn("docs/a.md", seen)

    def test_missing_directory_still_fails(self):
        with self.assertRaises(ValueError):
            reachable({"README.md": "[sources](missing/)"})

    def test_successor_only_received_identical_project_copy(self):
        worker = files_under(TRIAL / "worker/case")
        successor = files_under(TRIAL / "successor/case")
        self.assertEqual(worker, successor)
        self.assertFalse(any("inbox/" in p or "authorization" in p for p in successor))

    def test_successor_reply_links_resolve_from_its_output_location(self):
        output = "successor/outputs/reply.md"
        refs = LINK.findall((TRIAL / output).read_text(encoding="utf-8"))
        self.assertTrue(refs)
        for ref in refs:
            self.assertTrue((TRIAL / local_target(output, ref)).is_file(), ref)

    def test_runtime_and_nonmutable_originals_stayed_frozen(self):
        protected = json.loads((TRIAL / "input-manifest.json").read_text(encoding="utf-8"))
        for name, expected in protected.items():
            if name.startswith("runtime/") or name in ("PLAN.md", "worker/request-1.md", "prior-response.md"):
                self.assertEqual(digest(TRIAL / name), expected, name)

    def test_semantic_assessment_is_independent_and_bounded(self):
        result = self.record
        self.assertTrue(result["simulation_only"])
        self.assertFalse(result["real_transport_verified"])
        self.assertFalse(result["normal_operation_verified"])
        self.assertTrue(result["evaluation"]["text"].strip())
        self.assertNotEqual(result["worker_agent"], result["evaluator_agent"])
        # Never infer a pass from a preferred phrase or the worker's self-assessment.


if __name__ == "__main__":
    unittest.main()
